// Result-specific discovery and monitoring. The ordinary resource portal stays independent.
export function createResultViews(ctx){
  const {esc,field,form,B,table,tr,tag,link,api,modal,nav,toast}=ctx;
  const D=()=>ctx.state().D,I=()=>D().integration,R=()=>I().results;
  const params=()=>new URLSearchParams(location.hash.split('?')[1]);
  const url=(tab,values={})=>'#/admin/integration-results?'+new URLSearchParams({tab,...values});
  let request=0,cache=null,cacheKey='',error='';
  const empty=t=>`<p class="empty">${esc(t)}</p>`;
  const metrics=o=>`<div class="ct-metrics ir-metrics">${Object.entries(o).map(([label,value])=>`<div class="panel ig-metric"><span>${esc(label)}</span><strong>${esc(value??'未登记')}</strong></div>`).join('')}</div>`;
  function cards(rows){return `<div class="ct-cards">${rows.map(r=>`<article class="panel ct-card"><div>${tag(r.group)}<small>${esc(r.group==='工具'?r.toolCategory:r.theme||'未归类')}</small></div><h3>${esc(r.name)}</h3><p>${esc(r.description||'原中心尚未补充介绍')}</p><small>提供方：${esc(r.provider)}</small><small>发布：${esc(r.publishedAt||'未登记')} · 更新：${esc(r.updated||'未登记')}</small><div class="actions">${B('详情','result-detail',r.id)}${B(r.group==='工具'?'打开工具':'进入应用','open',r.id)}${B(D().centers.favorites.includes(r.id)?'取消收藏':'收藏','favorite',r.id)}${r.manual?link('使用手册',r.manual):''}</div></article>`).join('')||empty('当前分类暂无可见的已发布内容')}</div>`;}
  function directory(tab){const tools=tab==='tools',rows=R()[tools?'tools':'scenes'],p=params(),query=p.get('query')||'',category=p.get('category')||'',theme=p.get('theme')||'',provider=p.get('provider')||'';
    const categories=[...new Set(rows.map(r=>r.toolCategory))];
    const filtered=rows.filter(r=>(!query||[r.name,r.description,r.provider,r.theme,r.toolCategory].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!category||r.toolCategory===category)&&(!theme||(theme==='未归类'?!r.theme:r.theme===theme))&&(!provider||r.provider===provider));
    const totalPages=Math.max(1,Math.ceil(filtered.length/12)),page=Math.min(totalPages,Math.max(1,parseInt(p.get('page'))||1));
    const countNav=tools?`<nav class="ig-section-nav" aria-label="工具能力分类">${[['','全部工具'],...categories.map(k=>[k,k])].map(([k,n])=>`<a href="${url(tab,{category:k})}" ${category===k?'aria-current="page"':''}>${esc(n)} <b>${k?rows.filter(r=>r.toolCategory===k).length:rows.length}</b></a>`).join('')}</nav>`:`<div class="ir-themes">${[...I().themes,'未归类'].map(t=>{const count=rows.filter(r=>(r.theme||'未归类')===t).length,systems=R().systems.filter(r=>r.theme===t);return `<a class="panel ir-theme ${theme===t?'active':''}" href="${url(tab,{theme:t})}"><strong>${esc(t)}</strong><span>${count} 个应用 · ${systems.length} 个关联系统</span><small>${count?'已发布应用可访问':systems.length?'已有系统关联，专题应用待接入':'尚无可见接入内容'}</small></a>`;}).join('')}</div>`;
    const systems=tools?[]:R().systems.filter(r=>(!theme||r.theme===theme)&&(!provider||r.provider===provider)&&(!query||[r.name,r.provider,r.theme].join(' ').includes(query)));
    return countNav+`<form id="ig-result-search" class="ig-admin-filter">${field('query',tools?'工具名称 / 说明':'场景 / 系统关键词',query)}${tools?field('category','工具能力分类',category,'select',[['','全部分类'],...categories]):field('theme','业务主题',theme,'select',[['','全部主题'],...I().themes,'未归类'])}${field('provider','提供方',provider,'select',[['','全部提供方'],...[...new Set([...rows,...(tools?[]:R().systems)].map(r=>r.provider))]])}<button class="btn primary" type="submit">查询</button>${link('重置',url(tab))}</form><div class="ig-section-heading"><h2>${tools?'工具目录':'应用目录'} · ${filtered.length}</h2>${link(tools?'工具集成监测':'场景集成监测',url('usage',{domain:tools?'tools':'scenes'}))}</div>${cards(filtered.slice((page-1)*12,page*12))}<div class="pagination">第 ${page} / ${totalPages} 页 ${page>1?link('上一页',url(tab,{...Object.fromEntries(p),tab,page:page-1})):''}${page<totalPages?link('下一页',url(tab,{...Object.fromEntries(p),tab,page:page+1})):''}</div>${tools?'':`<section class="panel ct-panel"><h2>主题关联业务系统 · ${systems.length}</h2><p class="muted">系统入口沿用原接入配置。入口已配置不代表单点登录已联通。</p>${table(['系统','业务主题','提供方','接入情况','访问'],systems.map(r=>tr(esc(r.name),esc(r.theme),esc(r.provider),tag(r.status),r.entry?B('访问系统','result-system-open',r.id):'待配置访问入口')))}</section>`}`;
  }
  function bars(rows,withLink=false){const max=Math.max(1,...rows.map(r=>r.count));return rows.length?`<div class="ir-bars">${rows.map(r=>`<div><span>${withLink?B(r.name,'result-detail',r.id):esc(r.name)}</span><meter min="0" max="${max}" value="${r.count}">${r.count}</meter><b>${r.count}${r.percent!=null?' · '+r.percent+'%':''}</b></div>`).join('')}</div>`:empty('暂无符合口径的记录');}
  function chart(rows){const total=rows.reduce((n,r)=>n+r.count,0);let end=0;const colors=['#317b66','#6f98ce','#d1a653','#9981bc','#78aa95','#c67c70','#7d8a93'];const stops=rows.map((r,i)=>{const start=end;end+=total?r.count/total*100:0;return `${colors[i%colors.length]} ${start}% ${end}%`;});return total?`<div class="ir-chart"><div class="ir-donut" role="img" aria-label="分类数量：${esc(rows.map(r=>r.name+' '+r.count).join('，'))}" style="background:conic-gradient(${stops.join(',')})"><span>${total}</span></div>${bars(rows)}</div>`:empty('尚无分类记录');}
  function usage(){const p=params(),domain=['layers','tools','scenes'].includes(p.get('domain'))?p.get('domain'):'layers';const rows=R()[domain];
    let html=`<nav class="ig-section-nav" aria-label="成果监测对象">${[['layers','图层全链路监测'],['tools','工具集成监测'],['scenes','场景集成监测']].map(([k,n])=>`<a href="${url('usage',{domain:k})}" ${k===domain?'aria-current="page"':''}>${n}</a>`).join('')}</nav><form id="ig-result-stats" class="ig-admin-filter">${field('start','开始日期',p.get('start')||'','date')}${field('end','结束日期',p.get('end')||'','date')}${field('period','趋势粒度',p.get('period')||'day','select',[['day','日'],['week','周'],['month','月']])}${field('activity','趋势 / 排行口径',p.get('activity')||(domain==='layers'?'layerQuery':domain==='tools'?'call':'open'),'select',domain==='layers'?[['layerQuery','空间查询'],['call','成功服务调用'],['open','入口访问']]:domain==='tools'?[['call','成功调用'],['open','入口访问']]:[['open','入口访问']])}${field('department','调用部门',p.get('department')||'','select',[['','全部部门'],...(cache?.departments||[])])}${field('resource','对象',p.get('resource')||'','select',[['','全部对象'],...rows.map(r=>[r.id,r.name])])}<button class="btn primary">统计查询</button>${link('重置',url('usage',{domain}))}</form>`;
    const key=D().user.id+location.hash+D().serverTime;if(cacheKey!==key)return html+'<p role="status">正在读取当前可见范围的统计…</p>';
    if(error)return html+`<p role="alert">${esc(error)}</p>${B('重试','result-stats-retry')}`;if(!cache)return html+'<p role="status">正在读取统计…</p>';
    const m=cache,eventName={layerQuery:'空间查询',call:'成功调用',open:'入口访问'}[cache.activity],value=e=>cache.activity==='layerQuery'?e.queries:cache.activity==='call'?e.calls:e.opens;
    html+=metrics({'当前对象':m.total,'提供部门':m.providers,['累计'+eventName]:value(m.cumulative),['本月'+eventName]:value(m.month),'累计使用人数':m.cumulative.users})+`<p class="notice">${esc(m.scope)}</p>`+metrics({['筛选期'+eventName]:value(m.filtered),'筛选期使用人数':m.filtered.users,'筛选期入口访问':m.filtered.opens});
    if(domain==='scenes')html+=metrics({'可见关联系统':m.systems.length,'已配置系统入口':m.systems.filter(r=>r.entry).length,'系统入口待配置':m.systems.filter(r=>!r.entry).length})+`<p class="muted">应用和关联系统分别统计；不将配置入口视为认证联通。</p>`;
    if(domain==='layers')html+=`<section class="panel ct-panel"><h2>资源规模与汇聚登记</h2>${metrics({'可见数据库表':m.scale.dataTables,'矢量图层':m.scale.vectorLayers,'栅格图层':m.scale.rasterLayers,'证照图层':m.scale.certificateLayers,'形态未登记图层':m.scale.unclassifiedLayers})}<p>规模按当前全部可见已发布对象统计；栅格与证照按目录图层计数，不等同文件数或证照份数。</p>${metrics({'已登记容量（字节）':m.capacityBytes,'容量已登记对象':m.capacityKnown,'容量未登记对象':m.total-m.capacityKnown})}<p>容量仅汇总 ${m.capacityKnown} / ${m.total} 个已登记图层；数据表按原资源对象去重统计，不计为图层。未登记不能视为零容量。</p><div class="ig-columns"><div><h3>厅内 / 厅外来源</h3>${bars(m.sourceScopes)}</div><div><h3>汇聚状态（人工登记）</h3>${bars(m.collectionStates)}</div></div></section>`;
    html+=`<div class="ig-columns">${[['分类结构',chart(m.classification)],['提供部门数量与占比',bars(m.providerDistribution)],['按'+({day:'日',week:'周',month:'月'}[p.get('period')||'day'])+'统计'+eventName,bars(m.trend)],[eventName+'排行',bars(m.rankings,true)],['调用部门排行',bars(m.departmentRanks)]].map(([title,body])=>`<section class="panel ct-panel"><h2>${title}</h2>${body}</section>`).join('')}</div>`;
    return html;
  }
  function management(){const scope=params().get('scope')||({'工具':'tools','应用场景':'scenes','服务':'layers'}[params().get('filter')]||(params().get('filter')?'resources':'layers')),rows=scope==='resources'?I().catalog.filter(r=>!params().get('filter')||r.group===params().get('filter')):R()[scope]||[];return `<nav class="ig-section-nav">${[['layers','图层目录登记'],['tools','工具展示分类'],['scenes','应用主题归类'],['systems','主题关联系统'],['resources','其他资源展示分类']].map(([k,n])=>link(n,'#/admin/integration-settings?tab=placement&scope='+k)).join('')}</nav>`+(scope==='systems'?table(['原系统','主题','可见角色','配置'],D().centers.systems.map(r=>{const cfg=I().resultSystems[r.id]||{};return tr(esc(r.name),esc(cfg.theme||'未关联'),esc((cfg.roles||[]).join('、')||'仅管理员'),B('关联主题与可见范围','result-system-edit',r.id));})):table(['名称','当前分类','提供方','维护'],rows.map(r=>tr(esc(r.name),esc(scope==='layers'?r.layerTheme:scope==='tools'?r.toolCategory:scope==='resources'?r.placement.theme||r.group:r.theme||'未归类'),esc(r.provider||r.source||'未登记'),scope==='layers'?B('目录与监测登记','result-layer-edit',r.resourceId):B('展示分类','placement',r.id)))));
  }
  function bind(tab){const f=document.querySelector('#ig-result-search');if(f)f.onsubmit=e=>{e.preventDefault();nav(url(tab,Object.fromEntries(new FormData(f))).slice(1));};const statsForm=document.querySelector('#ig-result-stats');if(statsForm)statsForm.onsubmit=e=>{e.preventDefault();nav(url('usage',{domain:params().get('domain')||'layers',...Object.fromEntries(new FormData(statsForm))}).slice(1));};
    if(tab==='usage'){const key=D().user.id+location.hash+D().serverTime;if(cacheKey!==key){cacheKey=key;cache=null;error='';const token=++request;api('integration.results.stats',Object.fromEntries(params())).then(r=>{if(token!==request)return;cache=r;ctx.render();}).catch(e=>{if(token!==request)return;error=e.message;ctx.render();});}}
  }
  async function action(op,id){
    if(op==='result-stats-retry'){cacheKey='';ctx.render();return true;}
    if(op==='result-detail'){const r=[...R().layers,...R().tools,...R().scenes].find(r=>r.id===id);if(!r)throw Error('对象已不可见，请刷新');const values=[['类型',r.kind],['业务分类',r.layerTheme||r.theme||r.toolCategory],['发布单位',r.publisher],['提供方',r.provider],['发布时间',r.publishedAt||'原中心未登记'],['更新时间',r.updated||'未登记'],['更新频率',r.frequency],['使用权限',r.authorized===false?'需申请；目录可见不代表数据可用':'使用时重新校验授权']];modal(r.name,`<dl class="ig-detail">${values.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v||'未登记')}</dd>`).join('')}</dl><h3>详细介绍</h3><p>${esc(r.description||'原中心尚未补充')}</p><div class="actions">${B('进入使用 / 申请','open',id)}${r.manual?link('使用手册',r.manual):'<small>暂未登记使用手册</small>'}</div>`,true);return true;}
    if(op==='result-system-open'){const r=await api('integration.results.system.open',{id});if(r.external)modal('访问业务系统',`<p>原系统可能要求独立认证。</p><a class="btn primary" href="${esc(r.target)}" target="_blank" rel="noopener noreferrer">打开系统</a>`);else nav(r.target.replace(/^#/,''));return true;}
    if(!I().canManage)return false;
    if(op==='result-system-edit'){const s=D().centers.systems.find(r=>r.id===id),r=I().resultSystems[id]||{rev:0};form('场景关联系统 · '+s.name,field('theme','业务主题',r.theme||I().themes[0],'select',I().themes)+field('provider','提供部门',r.provider||'')+field('roles','允许使用的角色',r.roles||[],'multi',[...new Set(D().accounts.map(u=>u.role))])+field('enabled','启用主题关联',r.enabled||false,'check')+'<p>继续使用原系统的入口和认证配置；若关联应用，使用者还须有该应用的访问权限。</p>',v=>ctx.send('results.system.save',{id,rev:r.rev,values:v}));return true;}
    if(op==='result-layer-edit'){const layer=R().layers.find(r=>r.resourceId===id),r=I().layerMetadata[id]||{rev:0};form('图层目录与汇聚登记 · '+layer.name,field('theme','主题路径（用 / 分层，最多4级）',r.theme||layer.layerTheme)+field('department','提供部门',r.department||layer.provider)+field('cities','盟市标签（逗号或换行分隔）',(r.cities||layer.cities).join('，'))+field('hotspots','热点标签（逗号或换行分隔）',(r.hotspots||[]).join('，'))+field('dataKind','数据形态',r.dataKind||'未登记','select',['未登记','矢量','栅格','证照'])+field('sourceScope','来源范围',r.sourceScope||'未登记','select',['未登记','厅内','厅外'])+field('collectionState','汇聚状态（人工登记）',r.collectionState||'未登记','select',['未登记','待接入','接入中','已接入','异常'])+field('capacityBytes','已核实容量（字节，留空未登记）',r.capacityBytes??'')+'<p>仅登记已核实信息；保存分类不代表完成外部服务接入。</p>',v=>{for(const k of ['cities','hotspots'])v[k]=v[k].split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);v.capacityBytes=v.capacityBytes.trim()===''?null:Number(v.capacityBytes);return ctx.send('layer.metadata',{id,rev:r.rev,values:v});});return true;}
    return false;
  }
  return {directory,usage,management,bind,action,reset(){request++;cacheKey='';cache=null;}};
}
